'@

if (Test-Path -LiteralPath $Destination) {
    $existing = Get-ChildItem -LiteralPath $Destination -Force -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($existing -and -not $Force) {
        throw "Destination exists and is not empty. Choose an empty destination or pass -Force."
    }
    if ($Force) {
        Remove-Item -LiteralPath $Destination -Recurse -Force
    }
}

New-Item -ItemType Directory -Path $Destination -Force | Out-Null
$resolvedDestination = (Resolve-Path -LiteralPath $Destination).Path
$zipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("cdt-workflow-" + [Guid]::NewGuid().ToString("N") + ".zip")
try {
    $cleanBase64 = $Base64Zip -replace '\s', ''
    [System.IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($cleanBase64))
    $actualSha256 = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash
    if ($actualSha256 -ne $ExpectedSha256) {
        throw "Bundle SHA256 mismatch. Expected $ExpectedSha256 but got $actualSha256."
    }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $resolvedDestination)
    Write-Host "Restored CDT Workflow source bundle to $resolvedDestination"
    Write-Host "SHA256: $ExpectedSha256"
}
finally {
    Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
}
